declare(strict_types=1);require_once __DIR__.'/bootstrap.php';learning_require_login();$slug=defined('LEARNING_LANGUAGE')?LEARNING_LANGUAGE:'html';$c=learning_course($slug);$pdo=learning_pdo();$s=$pdo->prepare("SELECT p.*,l.title lesson_title FROM learning_practice p JOIN learning_lessons l ON l.id=p.lesson_id WHERE l.module_id IN(SELECT id FROM learning_modules WHERE course_id=?) ORDER BY p.sort_order");$s->execute([$c['id']]);$rows=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Practice</title><style>body{margin:0;background:#080a10;color:#fff;font-family:Inter,system-ui}.wrap{max-width:900px;margin:auto;padding:30px 18px}.item{padding:16px;border:1px solid #fff1;border-radius:12px;background:#10151e;margin:8px 0}a{color:#a78bfa;text-decoration:none}.meta{color:#788398;font-size:8px}</style></head><body><div class="wrap"><a href="index.php">← Course</a><h1>💻 Practice</h1><?php if(!$rows):?><p class="meta">Practice tasks will appear here as they are added to the database.</p><?php endif;?><?php foreach($rows as $r):?><div class="item"><strong style="font-size:10px"><?=eh($r['title'])?></strong><div class="meta"><?=eh($r['lesson_title'])?> · <?=eh($r['difficulty'])?></div></div><?php endforeach;?></div></body></html>